import{_ as a,y as r,a as o,o as n,a2 as s,D as i,g as d}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":1786355127000}'),l={name:"getting-started/introduction.md"};function g(h,e,c,p,m,u){const t=r("ImagePopup");return n(),o("div",null,[e[0]||(e[0]=s('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://bagisto.com/en/" target="_blank" rel="noreferrer">Bagisto</a> is a fantastic open-source eCommerce platform that allows businesses to create modern online stores easily. Bagisto offers a wide range of customizable features to meet the specific needs of any online business.</p><p>The platform is built on top of the reliable <a href="https://laravel.com/" target="_blank" rel="noreferrer">Laravel</a> framework, <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> and <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js</a>, a user-friendly JavaScript framework. It provides businesses with a user-friendly interface and powerful tools to manage their online stores, handle inventory and orders, and create a smooth shopping experience for customers</p><h3 id="navigating-the-admin-panel" tabindex="-1">Navigating the Admin Panel <a class="header-anchor" href="#navigating-the-admin-panel" aria-label="Permalink to &quot;Navigating the Admin Panel&quot;">​</a></h3><p><strong>Bagisto</strong> reworks the admin menu to support <strong>three levels</strong>, so sections with their own sub-pages are reachable without leaving the sidebar. For example, <strong>Settings &gt;&gt; Taxes</strong> now opens <strong>Tax Categories</strong> and <strong>Tax Rates</strong> beneath it, and <strong>Settings &gt;&gt; Data Transfer</strong> opens <strong>Imports</strong>.</p><h3 id="working-with-the-listing-grids" tabindex="-1">Working with the Listing Grids <a class="header-anchor" href="#working-with-the-listing-grids" aria-label="Permalink to &quot;Working with the Listing Grids&quot;">​</a></h3><p>Most admin screens are listing grids — products, orders, customers, imports, and so on. They all share the same header, search box, <strong>Filter</strong> control, and pagination.</p><p>On a small screen, grids that define their own layout, such as <strong>Catalog &gt;&gt; Products</strong>, are shown as cards instead of a wide table. The column header is dropped there, because <strong>Filter</strong> and <strong>Sort By</strong> are reachable from the bar fixed to the foot of the screen. Grids that use the default layout keep the table and scroll sideways.</p>',8)),i(t,{src:"/images/getting-started/mobileDatagrid.png",alt:"Admin Listing Grid on Mobile"}),e[1]||(e[1]=d("p",null,"While a grid is loading, the placeholders now match the grid they stand in for on both desktop and mobile, so the layout no longer shifts once the rows arrive.",-1))])}const w=a(l,[["render",g]]);export{b as __pageData,w as default};
